const response = $json;
if (!response?.success) throw new Error('A API não confirmou a reserva do job.');
if (response.empty || !response.data?.job?.id) return [];
const channels = response.data.campaign?.creative_campaign_channels;
if (!Array.isArray(channels) || channels.length === 0) throw new Error('A campanha reservada não possui canais.');
return [{ json: response.data }];

const data = $json;
const campaign = data.campaign;
const product = data.product || null;
const brand = data.brand_profile || {};
const channels = campaign.creative_campaign_channels.map((channel) => ({
  channel_id: channel.id,
  platform: channel.platform,
  formats: channel.formats || [],
  configuration: channel.configuration || {}
}));
const context = {
  campaign: {
    title: campaign.title,
    objective: campaign.objective,
    primary_destination: campaign.primary_destination,
    audience: campaign.audience,
    locale: campaign.locale || 'pt-BR',
    include_price: Boolean(campaign.include_price),
    brief: campaign.brief || {}
  },
  product: product ? {
    id: product.id,
    name: product.name,
    description: product.description,
    sale_price: campaign.include_price ? product.sale_price : null
  } : null,
  brand_profile: brand,
  channels
};
const prompt = [
  'Atue como estrategista sênior de comércio local e copywriter multicanal.',
  'Crie uma estratégia central e uma copy realmente própria para cada plataforma solicitada.',
  'Responda somente com um objeto JSON válido, sem markdown.',
  'Não invente especificações, certificações, garantia, estoque, desconto, prazo, endereço, taxa de entrega ou condição de pagamento.',
  'Nunca use original, oficial ou homologado sem comprovação explícita nos dados.',
  'Evite linguagem que sugira falsificação, réplica ou associação indevida com fabricantes.',
  'Se include_price for falso, não mencione preço. Se for verdadeiro, use somente sale_price quando disponível.',
  'Adapte gancho, argumento, extensão, CTA, hashtags e estilo para cada canal.',
  'Para WhatsApp, produza mensagem curta, natural e pronta para envio. Para vídeo curto, inclua gancho e roteiro quando adequado.',
  'Preserve exatamente cada channel_id recebido.',
  'Estrutura obrigatória: {"strategy":{"positioning":"","central_promise":"","audience_insight":"","offer_angle":"","compliance_notes":[]},"channels":[{"channel_id":"uuid","platform":"","copy":{"headline":"","primary_text":"","description":"","cta":"","hashtags":[],"whatsapp_message":"","video_hook":"","short_script":"","compliance_notes":[]}}]}',
  'Devolva exatamente um item em channels para cada canal fornecido, sem adicionar ou remover canais.',
  'DADOS DA CAMPANHA:',
  JSON.stringify(context)
].join('\n');
return [{json:{...data, expected_channels:channels, strategy_prompt:prompt, openai_request:{model:'gpt-5.4',reasoning:{effort:'high'},text:{format:{type:'json_object'}},input:[{role:'system',content:[{type:'input_text',text:'Você produz estratégia comercial multicanal segura e responde apenas em JSON válido.'}]},{role:'user',content:[{type:'input_text',text:prompt}]}]}}}];

const source = $('Preparar Prompt Multicanal').first().json;
const response = $json;
let text = response.output_text;
if (!text && Array.isArray(response.output)) {
  text = response.output.flatMap((item) => item.content || []).map((part) => part.text || '').join('');
}
if (!text || typeof text !== 'string') throw new Error('A OpenAI não retornou texto utilizável.');
let result;
try { result = JSON.parse(text); } catch { throw new Error('A OpenAI retornou JSON inválido.'); }
if (!result.strategy || !Array.isArray(result.channels)) throw new Error('Resultado sem strategy ou channels.');
const expected = new Map(source.expected_channels.map((c) => [c.channel_id, c.platform]));
if (result.channels.length !== expected.size) throw new Error('Quantidade de canais diferente da campanha.');
const seen = new Set();
const channels = result.channels.map((entry) => {
  if (!entry || typeof entry !== 'object' || !expected.has(entry.channel_id)) throw new Error('channel_id inválido no resultado.');
  if (seen.has(entry.channel_id)) throw new Error('channel_id duplicado no resultado.');
  if (!entry.copy || typeof entry.copy !== 'object' || Array.isArray(entry.copy)) throw new Error('Copy inválida para um canal.');
  seen.add(entry.channel_id);
  return { channel_id: entry.channel_id, copy: { ...entry.copy, platform: expected.get(entry.channel_id) } };
});
return [{json:{job_id:source.job.id,worker_id:'n8n-central-criativos-v1',output:{strategy:result.strategy,model:response.model || 'gpt-5.4',openai_response_id:response.id || null,generated_at:new Date().toISOString()},channels}}];

const source = $('Preparar Prompt Multicanal').first().json;
const raw = $json || {};
const message = String(raw.error?.message || raw.message || raw.description || 'Falha durante a geração ou validação da copy.').slice(0, 2000);
return [{json:{job_id:source.job.id,worker_id:'n8n-central-criativos-v1',error_code:'CREATIVE_GENERATION_FAILED',error_message:message,output:{stage:'generation',failed_at:new Date().toISOString()}}}];
